(()=>{'use strict';for(const root of document.querySelectorAll('#expanded-reference-list,[data-reference-filter]')){const input=root.querySelector('input'),select=root.querySelector('select'),status=root.querySelector('[role="status"]'),rows=Array.from(root.querySelectorAll('tbody tr'));if(!input||!status)continue;function filter(){const q=(input.value||'').trim().toLocaleLowerCase('tr-TR'),kind=select?.value||'';let n=0,total=0;rows.forEach(row=>{const match=(!q||row.textContent.toLocaleLowerCase('tr-TR').includes(q))&&(!kind||row.dataset.kind===kind);row.hidden=!match;if(match){n++;total+=Number(row.dataset.count||1);}});status.textContent=root.hasAttribute('data-reference-filter')?n+' bölge/durum satırı · '+total+' arşiv kaydı gösteriliyor':n+' referans kaydı gösteriliyor';}input.addEventListener('input',filter);select?.addEventListener('change',filter);filter();}})();
